    }

    function _run(uint256 x) internal {
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 etherBefore = address(c).balance;
        bool reverted;
        try c.SetMinSum(x) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 etherAfter = address(c).balance;
        assertTrue(balAfter == balBefore && etherAfter == etherBefore);
    }

